CREATE TABLE `illustrations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `recordnumber` varchar(255) DEFAULT NULL,
  `relatedwork_id` int(16) unsigned DEFAULT NULL,
  `illustrationtitle` varchar(255) DEFAULT NULL,
  `keyword_id` varchar(255) DEFAULT NULL,
  `artists` int(16) unsigned DEFAULT NULL,
  `engravers` int(16) unsigned DEFAULT NULL,
  `worktype` int(16) unsigned DEFAULT NULL,
  `size` varchar(255) DEFAULT NULL,
  `startdate` varchar(255) DEFAULT NULL,
  `enddate` varchar(255) DEFAULT NULL,
  `sourcetext_id` int(16) unsigned DEFAULT NULL,
  `positioninsourcetext` varchar(255) DEFAULT NULL,
  `locationofcopy` varchar(255) DEFAULT NULL,
  `imagefilename` varchar(255) DEFAULT NULL,
  `notes` text,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1515 DEFAULT CHARSET=utf8;
