INSERT INTO `illustrations` VALUES (1,'MAG0001',28,'Waverley / \'Flora introduced a few irregular strains . . . seat of the fair harpress.\' [3 lines]','--- \n- \"225\"\n- \"155\"\n- \"30\"\n- \"36\"\n- \"41\"\n- \"47\"\n- \"60\"\n- \"74\"\n- \"351\"\n- \"102\"\n',95,44,3,'9.5 x 7.5','1829','1829',31,'vol. 1 (frontispiece)','EUL, Corson A.7.a.1829-33/1','','Depicts Flora MacIvor with her harp and attendants in the Glen at Glennaquoich, with Waverley observing [Ch. 22; EEWN 1, 115.9-14]. Legend dated June 1, 1829. ',NULL,'2009-04-10 10:51:10'),(2,'MAG0002',28,'\'He then invited his guest . . .with Ban and Buscar.\' [3 lines]','--- - \"35\" - \"26\" - \"50\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\"',58,84,3,'6 x 6.5','1829','1829',31,'vol. 1 (title-page vignette)','EUL, Corson A.7.a.1829-33/1','','Depicts Davie Gellatley in the environs of Tully-Veolan with dogs Ban and Buscar. [Ch. 12; EEWN 1, 57.35-37]',NULL,NULL),(3,'MAG0003',28,'Waverley / \'They found the good old careful officer . . . functions of clerk.\' [4 lines]','--- \n- \"323\"\n- \"163\"\n- \"11\"\n- \"53\"\n- \"88\"\n- \"93\"\n',73,88,3,'10 x 7.5','1829','1829',31,'vol. 2 (frontispiece)','EUL, Corson A.7.a.1829-33/2','0014650d.jpg#http://images.is.ed.ac.uk/luna/servlet/detail/UoEwal~1~1~57374~100311','Depicts Bradwardine in military uniform with Saunders Saunderson reading prayers to his troop prior to the battle of Prestonpans. [Ch. 46; EEWN 1, 237.9-15]. Legend dated June 1, 1829.',NULL,'2012-11-02 10:38:36'),(4,'MAG0004',28,'\'It makes me young again . . . might Sir Everard.\' [4 lines]','--- - \"11\" - \"12\" - \"102\" - \"97\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\"',97,44,3,'7.5 x 6','1829','1829',31,'vol. 2 (title-page vignette)','EUL, Corson A.7.a.1829-33/2','','Depicts Bradwardine greeting Waverley at the entrance of Tully-Veolan. [Ch. 10; EEWN 1, 45.27-30]',NULL,NULL),(5,'MAG0005',11,'Guy Mannering / \'He grinned . . . roof rung to his raptures.\' [2 lines]','--- - \"92\" - \"57\" - \"163\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\"',60,24,3,'10 x 7.5','1829','1829',31,'vol. 3 (frontispiece)','EUL, Corson A.7.a.1829-33/3','0007419d.jpg#http://images.is.ed.ac.uk/luna/servlet/detail/UoEwal~1~1~53643~100089','Depicts Dominie Sampson ecstatic in library at Woodbourne. [Ch. 20; EEWN 2, 109.17-18]',NULL,NULL),(6,'MAG0006',11,'\'Jock moved on . . . formidable jaw-hole.\' [3 lines]','--- \n- \"49\"\n- \"52\"\n- \"116\"\n- \"63\"\n- \"129\"\n',56,20,3,'7.5 x 6','1829','1829',31,'vol. 3 (title-page vignette)','EUL, Corson A.7.a.1829-33/3','','Depicts the young Mannering on horseback being guided over moorland by Jock Jabos to Ellangowan [Ch. 1; EEWN 2, 6.29-32].',NULL,'2009-06-25 14:47:27'),(7,'MAG0007',11,'Guy Mannering / \'A forfeit! A forfeit! . . . kingly character.\' [2 lines]','--- - \"83\" - \"24\" - \"240\" - \"33\" - \"67\" - \"188\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\"',56,70,3,'10 x 7.5','1829','1829',31,'vol. 4 (frontispiece)','EUL, Corson A.7.a.1829-33/4','','Depicts Pleydell at the game of High-Jinks in an Edinburgh tavern. [Ch. 36; EEWN 2, 206.3-4]',NULL,NULL),(8,'MAG0008',11,'\"Donner and blitzen!\" . . . have it then?\' [2 lines]','--- - \"42\" - \"37\" - \"85\" - \"142\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\"',24,25,3,'6 x 7.5','1829','1829',31,'vol. 4 (title-page vignette)','EUL, Corson A.7.a.1829-33/4','','Depicts Hatteraick grappling with Glossin in prison. [Ch. 57; EEWN 2, 351.4-5]',NULL,NULL),(9,'MAG0009',3,'The Antiquary / \'Oldbuck took him kindly . . . work into my account.\' [3 lines]','--- - \"79\" - \"73\" - \"29\" - \"8\" - \"140\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\" - \"\"',94,76,3,'10 x 7.5','1829','1829',31,'vol. 5 (frontispiece)','EUL, Corson A.7.a.1829-33/5','','Depicts Oldbuck consoling Saunders Mucklebackit by his boat after the drowning of his son Steenie. [Ch. 34; EEWN 3, 268.14-15]',NULL,NULL),(10,'M